#!/usr/bin/env python3
"""Generate synthetic .docx test fixtures with planted legal violations.

Produces 4 contracts into tests/fixtures/docx/:
  tourism.docx - турдоговор, 3 planted problems
  labor.docx   - трудовой договор, 4 planted problems
  lease.docx   - договор аренды, 3 planted problems
  clean.docx   - корректный договор услуг, no problems (false-positive control)

The planted problems are the exact sentences listed in
tests/fixtures/expected_findings.md (same wording, verbatim). No law article
numbers appear here - finding exact articles is the agent's job
(GLOBAl_RULES.md, working rule 3).

Regeneration is idempotent: existing files are overwritten.
"""
from __future__ import annotations

import argparse
from pathlib import Path

from docx import Document

FIXTURES_DIR = Path(__file__).resolve().parent / "docx"

# --- Planted problem sentences (verbatim, mirrored in expected_findings.md) ---

