# --- Shared helpers ---


def add_para(doc: Document, text: str) -> None:
    doc.add_paragraph(text)


def add_heading(doc: Document, text: str, level: int = 1) -> None:
    doc.add_heading(text, level=level)


def add_numbered(doc: Document, text: str) -> None:
    doc.add_paragraph(text, style="List Number")


def add_table(doc: Document, header: list[str], rows: list[list[str]]) -> None:
    table = doc.add_table(rows=1, cols=len(header))
    table.style = "Table Grid"
    for i, cell_text in enumerate(header):
        cell = table.rows[0].cells[i]
        cell.text = cell_text
        for run in cell.paragraphs[0].runs:
            run.bold = True
    for row in rows:
        cells = table.add_row().cells
        for i, value in enumerate(row):
            cells[i].text = value


def add_signatures(doc: Document, label_a: str, party_a: str, label_b: str, party_b: str) -> None:
    doc.add_paragraph()
    add_para(doc, f"{label_a}:                                                    {label_b}:")
    add_para(doc, f"{party_a:<35} {'':>20}{party_b}")
    add_para(doc, "подпись, печать                                               подпись")


