BUILDERS = {
    "tourism.docx": build_tourism,
    "labor.docx": build_labor,
    "lease.docx": build_lease,
    "clean.docx": build_clean,
}


def build_parser() -> argparse.ArgumentParser:
    return argparse.ArgumentParser(
        prog="generate_fixtures",
        description="Generate synthetic .docx contracts with planted legal violations.",
    )


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=FIXTURES_DIR,
        help=f"output directory (default: {FIXTURES_DIR})",
    )
    args = parser.parse_args(argv)
    args.output_dir.mkdir(parents=True, exist_ok=True)
    for name, builder in BUILDERS.items():
        doc = Document()
        builder(doc)
        path = args.output_dir / name
        doc.save(path)
        print(f"wrote {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
